from hypothesis import strategies as st

WORD = "snuke"
FILLER = "abcdfghijlmopqrtvwxyz"  # contains none of s, n, u, k, e


def _parse(inp):
    lines = inp.split("\n")
    h, w = (int(x) for x in lines[0].split())
    grid = lines[1:1 + h]
    return h, w, grid


def _solutions(h, w, grid):
    sols = []
    for r in range(h):
        for c in range(w):
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    cells = []
                    ok = True
                    for i in range(5):
                        rr, cc = r + i * dr, c + i * dc
                        if not (0 <= rr < h and 0 <= cc < w):
                            ok = False
                            break
                        if grid[rr][cc] != WORD[i]:
                            ok = False
                            break
                        cells.append((rr, cc))
                    if ok:
                        sols.append(tuple(cells))
    return sols


@st.composite
def gen(draw):
    h = draw(st.integers(5, 8))
    w = draw(st.integers(5, 8))
    grid = [[draw(st.sampled_from(FILLER)) for _ in range(w)] for _ in range(h)]
    while True:
        dr = draw(st.sampled_from([-1, 0, 1]))
        dc = draw(st.sampled_from([-1, 0, 1]))
        if dr != 0 or dc != 0:
            break
    if dr == 1:
        r = draw(st.integers(0, h - 5))
    elif dr == -1:
        r = draw(st.integers(4, h - 1))
    else:
        r = draw(st.integers(0, h - 1))
    if dc == 1:
        c = draw(st.integers(0, w - 5))
    elif dc == -1:
        c = draw(st.integers(4, w - 1))
    else:
        c = draw(st.integers(0, w - 1))
    for i in range(5):
        grid[r + i * dr][c + i * dc] = WORD[i]
    lines = [f"{h} {w}"] + ["".join(row) for row in grid]
    return "\n".join(lines) + "\n"


def validate(inp):
    try:
        lines = inp.split("\n")
        if lines[-1] == "":
            lines = lines[:-1]
        h, w = (int(x) for x in lines[0].split())
        if not (5 <= h <= 100 and 5 <= w <= 100):
            return False
        grid = lines[1:]
        if len(grid) != h:
            return False
        for row in grid:
            if len(row) != w or not all("a" <= ch <= "z" for ch in row):
                return False
        # uniqueness of the conforming set is guaranteed by the statement
        return len(_solutions(h, w, grid)) == 1
    except Exception:
        return False


def ref(inp):
    h, w, grid = _parse(inp)
    sols = _solutions(h, w, grid)
    r = sols[0]
    return "\n".join(f"{R + 1} {C + 1}" for R, C in r)
