FILLER = "abcdfghijlmopqrtvwxyz"  # no s, n, u, k, e: keeps the planted word unique


@st.composite
def gen(draw):
    H = draw(st.integers(5, 8))
    W = draw(st.integers(5, 8))
    dr, dc = draw(st.sampled_from(DIRS))
    starts = []
    for r in range(H):
        for c in range(W):
            if all(0 <= r + k * dr < H and 0 <= c + k * dc < W for k in range(5)):
                starts.append((r, c))
    r, c = draw(st.sampled_from(starts))
    grid = [[draw(st.sampled_from(FILLER)) for _ in range(W)] for _ in range(H)]
    for k in range(5):
        grid[r + k * dr][c + k * dc] = TARGET[k]
    rows = ["".join(row) for row in grid]
    return f"{H} {W}\n" + "\n".join(rows) + "\n"


def _parse(inp):
    t = inp.split()
    H, W = int(t[0]), int(t[1])
    rows = t[2:2 + H]
    return H, W, rows


def _solutions(H, W, rows):
    sols = []
    for r in range(H):
        for c in range(W):
            for dr, dc in DIRS:
                ok = True
                for k in range(5):
                    rr, cc = r + k * dr, c + k * dc
                    if not (0 <= rr < H and 0 <= cc < W) or rows[rr][cc] != TARGET[k]:
                        ok = False
                        break
                if ok:
                    sols.append((r, c, dr, dc))
    return sols


def validate(inp):
    try:
        t = inp.split()
        if len(t) < 2:
            return False
        H, W = int(t[0]), int(t[1])
        if not (5 <= H <= 100 and 5 <= W <= 100):
            return False
        if len(t) != 2 + H:
            return False
        rows = t[2:]
        for row in rows:
            if len(row) != W or not all("a" <= ch <= "z" for ch in row):
                return False
        return len(_solutions(H, W, rows)) == 1
    except Exception:
        return False


def ref(inp):
    H, W, rows = _parse(inp)
    sols = _solutions(H, W, rows)
    r, c, dr, dc = sols[0]
    lines = []
    for k in range(5):
        lines.append(f"{r + k * dr + 1} {c + k * dc + 1}")
    return "\n".join(lines)


